validate: {
  on: 'blur',
  fields: {
    name: (v) => (!v ? 'Required' : null),
    'addresses.*.postalCode': (v) => (!v ? 'Required' : null),
  },
}

import { z } from 'zod';
import { zodResolver, createResource } from 'qortex-resource';

const Schema = z.object({
  name: z.string().min(1),
  pricing: z.object({ basePrice: z.number().positive() }),
  addresses: z.array(z.object({
    city: z.string().min(1),
  })).min(1),
});

createResource({
  validate: { resolver: zodResolver(Schema), on: 'blur' },
  source: { save },
});

// Full form
const ok = await resource.validate();
if (!ok) console.log(resource.snapshot.errors);

// One path
await resource.validateField('email');
await resource.field('email').validate();

// Wizard step — only active paths
const stepOk = await resource.validateFields([
  'account.email',
  'account.password',
]);
if (stepOk) goNext();

// Custom blur in React
const slug = useField(resource, 'slug');

<input
  value={slug.value ?? ''}
  onChange={(e) => slug.onChange(e.target.value)}
  onBlur={async () => {
    slug.onBlur();
    const taken = await api.slugs.exists(slug.value);
    // show local UI error until first-class setErrors lands
    setSlugTaken(taken);
  }}
/>
